```csharp
using UnityEngine;

public class PlayerMovement : MonoBehaviour
{
    [Header("Settings")]
    [SerializeField] private float moveSpeed = 5f;
    [SerializeField] private float jumpForce = 5f;
    [SerializeField] private LayerMask groundLayer;
    [SerializeField] private Transform cameraTransform;

    [Header("References")]
    [SerializeField] private Rigidbody rb;
    [SerializeField] private Transform groundCheck;

    private Vector3 inputVector;
    private bool isGrounded;

    void Update()
    {
        // Read input every frame
        float x = Input.GetAxis("Horizontal");
        float z = Input.GetAxis("Vertical");
        inputVector = new Vector3(x, 0, z).normalized;

        if (Input.GetKeyDown(KeyCode.Space) && isGrounded)
        {
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
        }

        // Ground check using a small sphere overlap
        isGrounded = Physics.CheckSphere(groundCheck.position, 0.2f, groundLayer);
    }

    void FixedUpdate()
    {
        // Calculate movement relative to camera facing
        Vector3 forward = cameraTransform.forward;
        Vector3 right = cameraTransform.right;
        forward.y = 0;
        right.y = 0;
        forward.Normalize();
        right.Normalize();

        Vector3 moveDirection = (forward * inputVector.z + right * inputVector.x).normalized;
        rb.linearVelocity = new Vector3(moveDirection.x * moveSpeed, rb.linearVelocity.y, moveDirection.z * moveSpeed);
    }
}
```

Make sure to create an empty GameObject at your character's feet to act as the `groundCheck` transform. A common mistake is forgetting to set the `groundLayer` in the Inspector, which will result in the character being unable to jump!

