```csharp
using UnityEngine;
using System.Threading.Tasks;

public class DashAbility : MonoBehaviour
{
    [SerializeField] private float dashSpeed = 20f;
    [SerializeField] private float dashDuration = 0.2f;
    [SerializeField] private float cooldown = 1f;

    private Rigidbody rb;
    private float _cooldownRemaining;
    private float _previousDamping;
    private bool _isDashing;

    public bool IsDashing => _isDashing;
    public float CooldownRemaining => _cooldownRemaining;

    private void Awake() => rb = GetComponent<Rigidbody>();

    private void Update()
    {
        if (_cooldownRemaining > 0) _cooldownRemaining -= Time.deltaTime;
    }

    public async System.Threading.Tasks.Task<bool> TryDash(Vector3 direction)
    {
        if (_isDashing || _cooldownRemaining > 0 || direction.magnitude < 0.1f) return false;

        _isDashing = true;
        _cooldownRemaining = cooldown;

        // Capture state and prepare physics
        _previousDamping = rb.linearDamping;
        rb.useGravity = false;
        rb.linearDamping = 0;

        Vector3 horizontalDir = new Vector3(direction.x, 0, direction.z).normalized;
        Vector3 previousVelocity = rb.linearVelocity;

        // Execute Dash
        await Awaitable.WaitForSecondsAsync(dashDuration);

        // Restore state
        rb.useGravity = true;
        rb.linearDamping = _previousDamping;
        rb.linearVelocity = new Vector3(previousVelocity.x, rb.linearVelocity.y, previousVelocity.z);
        _isDashing = false;

        return true;
    }
}
```

A common mistake is forgetting to restore the `y` velocity component, which can cause the character to "teleport" to the ground or float if not handled correctly.

